import type { HTMLAttributes, Ref } from 'react';
import { cn } from '../../utils/cn';
import { skeletonVariants, type SkeletonVariantProps } from './skeleton.variants';

export interface SkeletonProps extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'children'>, SkeletonVariantProps {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** For `shape="text"`: number of lines; the last one is shorter. */
  lines?: number;
}

/**
 * Loading placeholder. Always decorative (aria-hidden): announce loading on the container,
 * e.g. `<div role="status" aria-label="Loading members">`. The pulse stops under reduced motion.
 */
export function Skeleton({ shape, lines = 1, className, ...props }: SkeletonProps) {
  const s = skeletonVariants({ shape });
  if (shape === 'text' && lines > 1) {
    return (
      <div aria-hidden className={cn(s.lines(), className)} {...props}>
        {Array.from({ length: lines }, (_, i) => (
          <div key={i} className={cn(s.block(), i === lines - 1 && 'w-2/3')} />
        ))}
      </div>
    );
  }
  return <div aria-hidden className={cn(s.block(), className)} {...props} />;
}

export { Skeleton, type SkeletonProps } from './Skeleton';
export { skeletonVariants, type SkeletonVariantProps } from './skeleton.variants';
export { doc as skeletonDoc } from './Skeleton.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const skeletonVariants = tv({
  slots: {
    block: 'animate-pulse bg-muted motion-reduce:animate-none',
    lines: 'grid gap-2',
  },
  variants: {
    shape: {
      block: { block: 'h-4 w-full rounded-md' },
      text: { block: 'h-3 w-full rounded-md' },
      circle: { block: 'size-10 shrink-0 rounded-full' },
    },
  },
  defaultVariants: { shape: 'block' },
});

export type SkeletonVariantProps = VariantProps<typeof skeletonVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Skeleton',
  group: 'Feedback',
  status: 'stable',
  description: 'Loading placeholder in the shape of the content: block, text (one or more lines, the last shorter) or circle. Pulses gently and stops under prefers-reduced-motion. Decorative; announce loading on the container.',
  tokens: ['muted'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
